/* bicg.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"


/* Array initialization. */
static
void init_array (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  /* Use local restrict-qualified pointers to help the compiler
     optimize and vectorize the initialization loops.  The PolyBench
     framework allocates these arrays as disjoint regions, so this
     assumption holds. */
  DATA_TYPE (*restrict A_)[m] = (DATA_TYPE (*restrict)[m])A;
  DATA_TYPE *restrict r_      = (DATA_TYPE *restrict)r;
  DATA_TYPE *restrict p_      = (DATA_TYPE *restrict)p;

  for (i = 0; i < m; i++)
    p_[i] = (DATA_TYPE)(i % m) / m;

  for (i = 0; i < n; i++) {
    r_[i] = (DATA_TYPE)(i % n) / n;
    DATA_TYPE *restrict Ai = A_[i];
    for (j = 0; j < m; j++)
      Ai[j] = (DATA_TYPE) (i*(j+1) % n) / n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
                 DATA_TYPE POLYBENCH_1D(s,M,m),
                 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_bicg [[gnu::flatten, gnu::noinline]] (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(s,M,m),
                 DATA_TYPE POLYBENCH_1D(q,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Use the PolyBench-provided (possibly instrumented) problem sizes
     for loop bounds. */
  const int mPB = _PB_M;
  const int nPB = _PB_N;

  /* Create local restrict-qualified views of the input/output arrays.
     This tells the compiler that the underlying memory regions do not
     overlap, which improves vectorization and allows it to keep
     scalars like q[i] in registers across the inner loop.

     The cast only changes the compiler's aliasing view; it does not
     change the actual addresses, so semantics are preserved as long
     as the arrays are indeed disjoint (which holds in PolyBench). */
  DATA_TYPE (*restrict A_)[mPB]      = (DATA_TYPE (*restrict)[mPB])A;
  DATA_TYPE *restrict s_             = (DATA_TYPE *restrict)s;
  DATA_TYPE *restrict q_             = (DATA_TYPE *restrict)q;
  const DATA_TYPE *restrict p_       = (const DATA_TYPE *restrict)p;
  const DATA_TYPE *restrict r_       = (const DATA_TYPE *restrict)r;

#pragma scop
  /* Initialize s to zero. */
  for (i = 0; i < mPB; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* BiCG kernel:
       q = A * p
       s = A^T * r

     The outer loop walks rows of A so that A[i][j] is accessed with
     unit stride in the inner loop, which is cache-friendly.  We keep
     the accumulation order exactly the same as in the original code. */
  for (i = 0; i < nPB; i++)
    {
      const DATA_TYPE ri = r_[i];
      const DATA_TYPE *restrict Ai = A_[i];
      DATA_TYPE qi = SCALAR_VAL(0.0);

      /* The inner loop has no loop-carried dependencies across j:
           - Each s_[j] is updated independently (the reduction for s
             is across the outer i-loop).
           - qi is a private scalar reduction for this i.
         The ivdep directive lets the compiler ignore any conservative
         dependency assumptions and vectorize more aggressively. */
#pragma GCC ivdep
      for (j = 0; j < mPB; j++)
        {
          const DATA_TYPE Aij = Ai[j];
          s_[j] += ri * Aij;
          qi    += Aij * p_[j];
        }

      /* Store q[i] once per row, after the inner loop.  This avoids
         repeated loads/stores of q[i] inside the inner loop while
         preserving the exact accumulation order and numerical result. */
      q_[i] = qi;
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
              POLYBENCH_ARRAY(A),
              POLYBENCH_ARRAY(r),
              POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
               POLYBENCH_ARRAY(A),
               POLYBENCH_ARRAY(s),
               POLYBENCH_ARRAY(q),
               POLYBENCH_ARRAY(p),
               POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
