#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <stddef.h> /* for size_t in optimized kernel */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"


/* Array initialization. */
static
void init_array (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  /* Precompute reciprocals to avoid repeated divisions. */
  const DATA_TYPE inv_m = SCALAR_VAL(1.0) / (DATA_TYPE)m;
  const DATA_TYPE inv_n = SCALAR_VAL(1.0) / (DATA_TYPE)n;

  /* Note: for 0 <= i < m, (i % m) == i, so we can drop the modulo. */
  for (i = 0; i < m; i++)
    p[i] = (DATA_TYPE)i * inv_m;

  /* Same here: for 0 <= i < n, (i % n) == i. */
  for (i = 0; i < n; i++) {
    r[i] = (DATA_TYPE)i * inv_n;

    /* Use a row pointer for better locality and less index arithmetic. */
    DATA_TYPE *Ai = A[i];
    for (j = 0; j < m; j++)
      Ai[j] = (DATA_TYPE)((i * (j + 1)) % n) * inv_n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
                 const DATA_TYPE POLYBENCH_1D(s,M,m),
                 const DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(s,M,m),
                 DATA_TYPE POLYBENCH_1D(q,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  /* Use local restrict-qualified pointers to help the compiler
     with alias analysis and enable aggressive vectorization. */
  DATA_TYPE *restrict s_ptr = s;
  DATA_TYPE *restrict q_ptr = q;
  DATA_TYPE *restrict p_ptr = p;
  DATA_TYPE *restrict r_ptr = r;
  DATA_TYPE *restrict A_ptr = &A[0][0];

#pragma scop
  /* Initialize s to 0.0. Using SCALAR_VAL ensures the proper
     DATA_TYPE is used (float or double). */
  for (int j = 0; j < _PB_M; ++j)
    s_ptr[j] = SCALAR_VAL(0.0);

  /* Main BiCG kernel: two matrix-vector products sharing the
     same traversal of A.
        s[j] += r[i] * A[i][j]
        q[i] += A[i][j] * p[j]
     We traverse A row-wise (contiguous in memory) and use
     pointer increments inside the inner loop to minimize
     index arithmetic and improve data locality. */
  for (int i = 0; i < _PB_N; ++i)
  {
    const DATA_TYPE r_i = r_ptr[i];
    DATA_TYPE q_i       = SCALAR_VAL(0.0);

    /* Pointer to the first element of row i of A.
       Each row has 'm' columns, matching the declaration in main(). */
    const DATA_TYPE *restrict Ai =
      A_ptr + (size_t)i * (size_t)m;

    /* Pointers that walk through s and p once per row. */
    DATA_TYPE *restrict sj       = s_ptr;
    const DATA_TYPE *restrict pj = p_ptr;

    for (int j = 0; j < _PB_M; ++j)
    {
      const DATA_TYPE a_ij = *Ai++;

      /* s[j] += r[i] * A[i][j]; */
      *sj += r_i * a_ij;

      /* q[i] += A[i][j] * p[j]; */
      q_i += a_ij * *pj;

      ++sj;
      ++pj;
    }

    q_ptr[i] = q_i;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
              POLYBENCH_ARRAY(A),
              POLYBENCH_ARRAY(r),
              POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
               POLYBENCH_ARRAY(A),
               POLYBENCH_ARRAY(s),
               POLYBENCH_ARRAY(q),
               POLYBENCH_ARRAY(p),
               POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
