#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"


/* Array initialization.
 *
 * Minor optimizations:
 * - Use local restrict-qualified pointers to help the compiler with
 *   alias analysis and indexing.
 * - Simplify the modulo operations in p[] and r[] initialization:
 *   for 0 <= i < m, (i % m) == i, and similarly for n.
 *   This is an exact integer identity and therefore preserves
 *   floating-point results bit-for-bit.
 */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  /* Create local restrict-qualified aliases for better optimization.
   * These are the only pointers used to access the underlying data in
   * this function, so the restrict assumptions are valid.
   */
  DATA_TYPE (* restrict A_)[m] = A;
  DATA_TYPE * restrict r_ = r;
  DATA_TYPE * restrict p_ = p;

  /* For 0 <= i < m, (i % m) == i; keep the division structure the same
   * as the original code to preserve floating-point semantics.
   */
  for (i = 0; i < m; i++)
    p_[i] = (DATA_TYPE)i / (DATA_TYPE)m;

  /* Similarly, for 0 <= i < n, (i % n) == i. */
  for (i = 0; i < n; i++) {
    r_[i] = (DATA_TYPE)i / (DATA_TYPE)n;

    /* Access row i through a local pointer to improve locality and
     * reduce address computation in the inner loop.
     */
    DATA_TYPE * restrict Ai = A_[i];
    for (j = 0; j < m; j++)
      Ai[j] = (DATA_TYPE)((i * (j + 1)) % n) / (DATA_TYPE)n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 * - Create restrict-qualified local aliases for all arrays to
 *   eliminate potential aliasing between A, s, q, p and r. This makes
 *   it easier for the compiler to vectorize and keep values in
 *   registers.
 * - Iterate over A by rows (i outer, j inner) as in the original code
 *   to keep memory accesses to A contiguous and cache-friendly.
 * - Hoist invariant loads (r[i]) out of the inner loop.
 * - Load A[i][j] once per iteration of the inner loop and reuse that
 *   value for both s[j] and q[i] updates, avoiding redundant loads.
 * - Use local scalar accumulator for q[i] to keep the reduction
 *   entirely in registers.
 * - Add a compiler hint (#pragma GCC ivdep) on the inner loop to
 *   state that there are no loop-carried dependencies across j
 *   iterations except the well-formed reduction on qi.
 */
static void __attribute__((noinline))
kernel_bicg (int m, int n,
	     DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
	     DATA_TYPE POLYBENCH_1D(s,M,m),
	     DATA_TYPE POLYBENCH_1D(q,N,n),
	     DATA_TYPE POLYBENCH_1D(p,M,m),
	     DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Local restrict-qualified aliases for better optimization. */
  DATA_TYPE (* restrict A_)[m] = A;
  DATA_TYPE * restrict s_ = s;
  DATA_TYPE * restrict q_ = q;
  DATA_TYPE * restrict p_ = p;
  DATA_TYPE * restrict r_ = r;

#pragma scop
  /* Initialize s to zero. */
  for (i = 0; i < _PB_M; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* BiCG kernel:
   *   s[j] = sum_i r[i] * A[i][j]
   *   q[i] = sum_j A[i][j] * p[j]
   */
  for (i = 0; i < _PB_N; i++)
    {
      /* Row i of A and corresponding scalar r[i]. */
      DATA_TYPE * restrict Ai = A_[i];
      const DATA_TYPE r_i = r_[i];

      /* Keep q[i] in a scalar accumulator. */
      DATA_TYPE qi = SCALAR_VAL(0.0);

      /* Inner loop is vectorizable:
       *  - s_[j] updates are independent across j
       *  - qi is a classic reduction variable
       */
#pragma GCC ivdep
      for (j = 0; j < _PB_M; j++)
	{
	  const DATA_TYPE a_ij = Ai[j];
	  s_[j] += r_i * a_ij;
	  qi    += a_ij * p_[j];
	}

      q_[i] = qi;
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
