#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Use restrict-qualified local aliases to help the optimizer with aliasing.
 *  - Precompute 1/m and 1/n to replace expensive divisions inside loops
 *    with cheaper multiplications.
 *  - Simplify (i % m) and (i % n) to i in ranges where this is always true.
 */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  /* Local restrict-qualified aliases for better optimization. */
  DATA_TYPE (* __restrict A_)[m] = A;
  DATA_TYPE * __restrict r_ = r;
  DATA_TYPE * __restrict p_ = p;

  /* Precompute reciprocals to avoid repeated divisions. */
  const DATA_TYPE inv_m = SCALAR_VAL(1.0) / (DATA_TYPE)m;
  const DATA_TYPE inv_n = SCALAR_VAL(1.0) / (DATA_TYPE)n;

  /* For 0 <= i < m: (i % m) == i. */
  for (i = 0; i < m; i++)
    p_[i] = (DATA_TYPE)i * inv_m;

  /* For 0 <= i < n: (i % n) == i. */
  for (i = 0; i < n; i++) {
    const DATA_TYPE ri = (DATA_TYPE)i * inv_n;
    r_[i] = ri;

    for (j = 0; j < m; j++) {
      int val = (i * (j + 1)) % n;
      A_[i][j] = (DATA_TYPE)val * inv_n;
    }
  }
}


