   including the call and return.
 *
 * Kernel performs:
 *   s[j] = sum_i r[i] * A[i][j]  (A^T * r)
 *   q[i] = sum_j A[i][j] * p[j]  (A * p)
 *
 * Optimizations:
 *  - Use restrict-qualified local aliases for all arrays to give the
 *    compiler strong aliasing guarantees (no overlap between A, s, q, p, r).
 *  - Hoist loop-invariant loads (r[i], A[i] row pointer) out of the inner loop.
 *  - Use a scalar accumulator (qi) in registers for q[i] instead of repeatedly
 *    loading/storing q[i] inside the inner loop.
 *  - Load A[i][j] once per iteration and reuse the value for both updates
 *    (s[j] and q[i]).
 *  - Add a vectorization hint (#pragma GCC ivdep) on the inner loop; this
 *    is safe because there are no loop-carried dependencies across j
 *    except the scalar reduction on qi, which the compiler handles.
 */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Local restrict-qualified aliases for better vectorization
     and instruction scheduling. */
  DATA_TYPE (* __restrict A_)[m] = A;
  DATA_TYPE * __restrict s_ = s;
  DATA_TYPE * __restrict q_ = q;
  DATA_TYPE * __restrict p_ = p;
  DATA_TYPE * __restrict r_ = r;

#pragma scop
  /* Initialize s to zero. This loop is trivially vectorizable. */
  for (i = 0; i < _PB_M; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* Single pass over A to compute:
   *   - q[i] = A[i][:] · p[:]
   *   - s[:] += r[i] * A[i][:]
   */
  for (i = 0; i < _PB_N; i++)
    {
      const DATA_TYPE ri = r_[i];   /* Loop-invariant for inner loop. */
      DATA_TYPE qi = SCALAR_VAL(0.0);
      DATA_TYPE * __restrict Ai = A_[i]; /* Pointer to current row of A. */

      /* Inner loop: good candidate for SIMD vectorization.
       *  - Ai[j] and p_[j] are accessed linearly.
       *  - s_[j] updates are independent across j.
       *  - qi is a scalar reduction.
       */
#pragma GCC ivdep
      for (j = 0; j < _PB_M; j++)
	{
	  const DATA_TYPE Aij = Ai[j];
	  s_[j] += ri * Aij;
	  qi    += Aij * p_[j];
	}

      q_[i] = qi;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
